package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.content.pm.*;import android.os.*;import java.io.*;import java.security.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import javax.net.ssl.HttpsURLConnection;
/** Optional public-release checks. Private ledger APIs are deliberately absent. */
final class AppUpdates {
 static final ExecutorService EXEC=Executors.newSingleThreadExecutor();static final Handler MAIN=new Handler(Looper.getMainLooper());static volatile boolean checking,downloading;static volatile int progress;static final Set<Runnable> observers=new HashSet<>();
 static android.content.SharedPreferences prefs(Context c){return c.getSharedPreferences("public-updates",0);}
 static String repo(Context c){return c.getString(R.string.update_repository);}
 static int installed(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode;}catch(Exception e){return 0;}}
 static ReleaseFeed.Release release(Context c){try{return ReleaseFeed.cached(new JSONObject(prefs(c).getString("release","")));}catch(Exception e){return null;}}
 static boolean available(Context c){ReleaseFeed.Release r=release(c);return r!=null&&r.code>installed(c);}
 static void observe(Runnable observer){observers.add(observer);}static void forget(Runnable observer){observers.remove(observer);}static void changed(){MAIN.post(()->{for(Runnable observer:new ArrayList<>(observers))observer.run();});}
 static void check(Context context,boolean manual){Context c=context.getApplicationContext();if(checking||!ReleaseFeed.repository(repo(c)))return;long last=prefs(c).getLong("attempt",0),interval=prefs(c).getString("error","").isEmpty()?24*60*60*1000L:60*60*1000L;if(!manual&&System.currentTimeMillis()-last<interval)return;checking=true;prefs(c).edit().putLong("attempt",System.currentTimeMillis()).putString("error","").apply();changed();EXEC.execute(()->{try{ReleaseFeed.Release r=ReleaseFeed.parse(repo(c),new JSONObject(UpdateNetwork.metadata(repo(c))));prefs(c).edit().putString("release",r.json().toString()).putLong("checked",System.currentTimeMillis()).putString("error","").apply();}catch(Exception e){prefs(c).edit().putString("error",friendly(e)).apply();}finally{checking=false;changed();}});}
 static String friendly(Exception e){return e instanceof java.net.UnknownHostException?"Sin conexión. Tus datos siguen disponibles.":e instanceof java.net.SocketTimeoutException?"La consulta tardó demasiado. Puedes volver a intentar.":e.getMessage()==null?"No se pudo completar la actualización":e.getMessage();}
 static File apk(Context c){File dir=new File(c.getCacheDir(),"updates");dir.mkdirs();return new File(dir,"Bolsillo-update.apk");}
 static boolean ready(Context c){ReleaseFeed.Release r=release(c);return r!=null&&available(c)&&prefs(c).getString("readyDigest","").equals(r.sha256)&&apk(c).isFile();}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(java.util.Locale.ROOT,"%02x",b&255));return s.toString();}
 static void verify(Context c,File file,ReleaseFeed.Release r)throws Exception{
  Ledger.require(file.length()==r.bytes&&file.length()<=ReleaseFeed.MAX_APK,"La descarga está incompleta");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))!=-1)digest.update(buffer,0,n);}Ledger.require(hex(digest.digest()).equals(r.sha256),"La huella de la descarga no coincide");PackageManager pm=c.getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo archive=pm.getPackageArchiveInfo(file.getAbsolutePath(),flags),current=pm.getPackageInfo(c.getPackageName(),flags);Ledger.require(archive!=null&&archive.applicationInfo!=null&&archive.applicationInfo.minSdkVersion<=Build.VERSION.SDK_INT&&c.getPackageName().equals(archive.packageName)&&archive.versionCode==r.code&&archive.versionCode>current.versionCode,"El APK no es una actualización de esta app");android.content.pm.Signature[] from=Build.VERSION.SDK_INT>=28?current.signingInfo.getApkContentsSigners():current.signatures,to=Build.VERSION.SDK_INT>=28?archive.signingInfo.getApkContentsSigners():archive.signatures;Ledger.require(from!=null&&to!=null&&from.length==1&&to.length==1&&MessageDigest.isEqual(from[0].toByteArray(),to[0].toByteArray()),"El APK no tiene la misma firma que tu app instalada");
 }
 static void download(Context context){Context c=context.getApplicationContext();ReleaseFeed.Release r=release(c);if(r==null||!available(c)||downloading)return;downloading=true;progress=0;prefs(c).edit().remove("readyDigest").putString("error","").apply();changed();EXEC.execute(()->{File file=apk(c);try{HttpsURLConnection connection=UpdateNetwork.open(new java.net.URL(r.url),false);try(InputStream in=connection.getInputStream();OutputStream out=new FileOutputStream(file)){byte[] buffer=new byte[32768];long total=0,last=0;int n;while((n=in.read(buffer))!=-1){total+=n;if(total>r.bytes||total>ReleaseFeed.MAX_APK)throw new IOException("La descarga excede el tamaño anunciado");out.write(buffer,0,n);long now=SystemClock.uptimeMillis();if(now-last>250){last=now;progress=(int)(total*100/r.bytes);changed();}}}finally{connection.disconnect();}verify(c,file,r);prefs(c).edit().putString("readyDigest",r.sha256).putString("error","").apply();progress=100;}catch(Exception e){file.delete();prefs(c).edit().remove("readyDigest").putString("error",friendly(e)).apply();}finally{downloading=false;changed();}});}
 static void install(Activity a)throws Exception{ReleaseFeed.Release r=release(a);Ledger.require(r!=null&&ready(a),"Descarga primero la actualización");if(Build.VERSION.SDK_INT>=26&&!a.getPackageManager().canRequestPackageInstalls()){a.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,android.net.Uri.parse("package:"+a.getPackageName())));return;}EXEC.execute(()->{int id=-1;try{verify(a,apk(a),r);PackageInstaller installer=a.getPackageManager().getPackageInstaller();PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(a.getPackageName());params.setSize(r.bytes);if(Build.VERSION.SDK_INT>=31)params.setRequireUserAction(PackageInstaller.SessionParams.USER_ACTION_REQUIRED);id=installer.createSession(params);prefs(a).edit().putInt("installSession",id).apply();try(PackageInstaller.Session session=installer.openSession(id)){try(InputStream input=new FileInputStream(apk(a));OutputStream out=session.openWrite("Bolsillo.apk",0,r.bytes)){byte[] bytes=new byte[32768];int n;while((n=input.read(bytes))!=-1)out.write(bytes,0,n);session.fsync(out);}Intent intent=new Intent(a,UpdateInstallReceiver.class).setAction("cl.bolsillo.INSTALL_RESULT");PendingIntent callback=PendingIntent.getBroadcast(a,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));session.commit(callback.getIntentSender());}}catch(Exception e){if(id>=0)try{a.getPackageManager().getPackageInstaller().abandonSession(id);}catch(Exception ignored){}prefs(a).edit().putString("error",friendly(e)).apply();changed();}});}
}
